// LÍMITES DE GASTO DIARIO - AJUSTAR SEGÚN NECESIDAD
const LIMITE_ALERTA = 10000;   // Alerta cuando supere $10.000 ARS
const LIMITE_CRITICO = 20000;  // Crítico cuando supere $20.000 ARS

const rows = $input.first().json[0]?.results || [];

if (rows.length === 0) {
  return [{ json: { alerta: false, mensaje: 'Sin datos' } }];
}

const row = rows[0];
const gasto = (row.metrics.costMicros || 0) / 1_000_000;
const conversiones = row.metrics.conversions || 0;
const valorConv = row.metrics.conversionsValue || 0;
const roas = gasto > 0 ? (valorConv / gasto).toFixed(2) : '0';

const hora = new Date().toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Argentina/Buenos_Aires' });

let nivelAlerta = 'OK';
let emoji = '✅';

if (gasto >= LIMITE_CRITICO) {
  nivelAlerta = 'CRITICO';
  emoji = '🚨';
} else if (gasto >= LIMITE_ALERTA) {
  nivelAlerta = 'ALERTA';
  emoji = '⚠️';
}

return [{
  json: {
    alerta: nivelAlerta !== 'OK',
    nivelAlerta,
    emoji,
    gasto: gasto.toFixed(0),
    gastoNum: gasto,
    conversiones,
    valorConv: valorConv.toFixed(0),
    roas,
    limiteAlerta: LIMITE_ALERTA,
    limiteCritico: LIMITE_CRITICO,
    hora,
    porcentajeLimite: ((gasto / LIMITE_ALERTA) * 100).toFixed(0)
  }
}];
